10	#include "ascendc_ir.h"
11	#include "graph/symbolizer/symbolic_utils.h"
12	
13	namespace af {
14	namespace ascir {
15	
16	constexpr int32_t kTwo = 2;
17	constexpr int32_t kFloatAlignSize = 8;
18	constexpr int32_t kPerformanceOptimization = 256;
19	constexpr int32_t kBlockSize = 32;
20	
21	static AscGraphAttr *GetOrCreateGraphAttrsGroup(const ComputeGraphPtr &graph) {
22	  GE_CHECK_NOTNULL_EXEC(graph, return nullptr;);
23	  auto attr = graph->GetOrCreateAttrsGroup<AscGraphAttr>();
24	  GE_CHECK_NOTNULL_EXEC(attr, return nullptr;);
25	  return attr;
26	}
27	
28	inline Expression GetAlignSize(Expression in) {
29	  return sym::Align(in, kFloatAlignSize);
30	}
31	
32	inline Expression GetByteSize(Expression in) {
33	  return sym::Mul(in, Symbol(sizeof(float)));
34	}
35	
36	bool IsNeedAccumulation(const AscNode &node) {
37	  if (node.GetType() == "Sum" || node.GetType() == "Mean" || node.GetType() == "Prod") {
38	    return true;
39	  }
40	  return false;
41	}
42	
43	std::vector<std::unique_ptr<TmpBufDesc>> CalcReduceTmpSize(const AscNode &node) {
44	  std::vector<std::unique_ptr<TmpBufDesc>> tmp_buf_desc;
45	  AscNodeInputs node_inputs = node.inputs;
46	  AscNodeOutputs node_outputs = node.outputs;
47	  if (node_inputs.Size() <= 0) {
48	    return tmp_buf_desc;
49	  }
50	
51	  if (node_outputs[0].attr.vectorized_strides.size() <= 0) {
52	    return tmp_buf_desc;
53	  }
54	
55	  bool isAr =
56	      SymbolicUtils::StaticCheckEq(node_outputs[0].attr.vectorized_strides.back(), sym::kSymbolZero) == TriBool::kTrue;
57	  auto attr = GetOrCreateGraphAttrsGroup(node.GetOwnerComputeGraph());
58	
59	  Expression r_in_ub_exp = Symbol(1);
60	  Expression a_in_ub_exp = Symbol(1);
61	  for (size_t i = 0; i < node_outputs[0].attr.vectorized_strides.size(); i++) {
62	    uint64_t vectorized_axis_id = node_outputs[0].attr.vectorized_axis[i];
63	    Expression tmp_exp = attr->axis[vectorized_axis_id]->size;
64	    if (i == node_outputs[0].attr.vectorized_strides.size() - 1) {
65	      tmp_exp = GetAlignSize(tmp_exp);
66	    }
67	
68	    if (SymbolicUtils::StaticCheckEq(node_outputs[0].attr.vectorized_strides[i], sym::kSymbolZero) == TriBool::kTrue &&
69	        SymbolicUtils::StaticCheckEq(node_inputs[0].attr.vectorized_strides[i], sym::kSymbolZero) != TriBool::kTrue) {
70	      r_in_ub_exp = sym::Mul(r_in_ub_exp, tmp_exp);
71	    } else {
72	      a_in_ub_exp = sym::Mul(a_in_ub_exp, tmp_exp);
73	    }
74	  }
75	
76	  Expression rFusedExpression = attr->axis[node.attr.sched.loop_axis]->size;
77	  if (IsNeedAccumulation(node)) {
78	    // 高阶API使用  a.UB * r.UB， ar场景需要加一个block，生命周期为-1
79	    Expression api_size = GetByteSize(sym::Mul(a_in_ub_exp, r_in_ub_exp));
80	    if (node.GetType() == "Prod") {
81	      api_size = sym::Add(api_size, Symbol(kPerformanceOptimization));
82	    }
83	    if (isAr) {
84	      api_size = sym::Add(api_size, Symbol(kBlockSize));
85	    }
86	    TmpBufDesc desc2 = {api_size, -1};
87	    tmp_buf_desc.emplace_back(std::make_unique<TmpBufDesc>(desc2));
88	
89	    // UB 间
90	    if (isAr) {
91	      a_in_ub_exp = GetAlignSize(a_in_ub_exp);
92	    }
93	    Expression a_size = GetByteSize(a_in_ub_exp);
94	    TmpBufDesc desc3 = {a_size, 0};
95	    tmp_buf_desc.emplace_back(std::make_unique<TmpBufDesc>(desc3));
96	  } else {
97	    // 高阶api部分 先按照最大的申请
98	    Expression api_size = GetByteSize(sym::Mul(a_in_ub_exp, r_in_ub_exp));
99	    TmpBufDesc desc1 = {api_size, -1};
100	    tmp_buf_desc.emplace_back(std::make_unique<TmpBufDesc>(desc1));
101	
102	    // UB 间
103	    if (isAr) {
104	      a_in_ub_exp = GetAlignSize(a_in_ub_exp);
105	    }
106	    Expression ub_size = GetByteSize(a_in_ub_exp);
107	
108	    // ArgMax 和 ArgMaxMultiRPhase2 需要额外的 tmp_buf
109	    // ArgMaxMultiRPhase1只需要生命周期为0的tmp_buf
110	    if (node.GetType() == "ArgMax" || node.GetType() == "ArgMaxMultiRPhase2") {
111	      // 生命周期为0的第一个tmp_buf：当前迭代的index临时存储
112	      TmpBufDesc desc2 = {sym::Mul(ub_size, Symbol(2)), 0};
113	      tmp_buf_desc.emplace_back(std::make_unique<TmpBufDesc>(desc2));
114	      // 生命周期为1的第一个tmp_buf：当前迭代的value临时存储
115	      TmpBufDesc desc3 = {ub_size, 1};
116	      tmp_buf_desc.emplace_back(std::make_unique<TmpBufDesc>(desc3));
117	      // 生命周期为2的tmp_buf：value的历史最大结果（R轴分核累加时使用）
118	      TmpBufDesc desc4 = {ub_size, 2};
119	      tmp_buf_desc.emplace_back(std::make_unique<TmpBufDesc>(desc4));
120	    } else if (node.GetType() == "ArgMaxMultiRPhase1") {
121	      // 生命周期为0的第一个tmp_buf：当前迭代的index临时存储
122	      TmpBufDesc desc2 = {sym::Mul(ub_size, Symbol(2)), 0};
123	      tmp_buf_desc.emplace_back(std::make_unique<TmpBufDesc>(desc2));
124	      // 生命周期为1的第一个tmp_buf：当前迭代的value临时存储
125	      TmpBufDesc desc3 = {ub_size, 1};
126	      tmp_buf_desc.emplace_back(std::make_unique<TmpBufDesc>(desc3));
127	    } else {
128	      TmpBufDesc desc2 = {ub_size, 0};
129	      tmp_buf_desc.emplace_back(std::make_unique<TmpBufDesc>(desc2));
130	    }
131	  }
132	
133	  return tmp_buf_desc;
134	}
135	}  // namespace ascir
136	}  // namespace af
