9	 */
10	#include "defalut_reg_func.h"
11	
12	namespace af {
13	namespace ascir {
14	
15	Expression GetCompareNormalNoLoopTmpSize(const AscNode &node, const std::vector<uint32_t> &axis_ids) {
16	  auto node_inputs = node.inputs;
17	  uint8_t typeSize = node_inputs[0].attr.dtype == ge::DataType::DT_FLOAT16 ? 2 : 4;
18	  EXPECT_SYMBOL_NE(Symbol(typeSize), Symbol(0));
19	  Expression compare_out_size = Symbol(256 / 8 / typeSize) * node_inputs[0].attr.repeats[axis_ids[0]];
20	  Expression select_out_size =
21	      Symbol(128) * ((node_inputs[0].attr.repeats[axis_ids[0]] * Symbol(2) + Symbol(typeSize - 1)) / Symbol(typeSize));
22	  return compare_out_size + select_out_size;
23	}
24	
25	std::vector<std::unique_ptr<TmpBufDesc>> GetCompareNormalTmpSize(const AscNode &node, const std::string &mode) {
26	  auto node_inputs = node.inputs;
27	  std::vector<uint32_t> axis_ids = {UINT32_MAX, UINT32_MAX};
28	  // 在axis中找到vectorized_axis最后一个元素在axis的位置
29	  uint32_t vec_last_axis_pos_in_axis = std::find(node_inputs[0].attr.axis.begin(), node_inputs[0].attr.axis.end(),
30	                                                 node_inputs[0].attr.vectorized_axis.back()) -
31	                                       node_inputs[0].attr.axis.begin();
32	  std::vector<std::unique_ptr<TmpBufDesc>> tmp_buf_descs;
33	  for (auto vec_axis : node_inputs[0].attr.vectorized_axis) {
34	    auto pos = std::find(node_inputs[0].attr.axis.begin(), node_inputs[0].attr.axis.end(), vec_axis);
35	    GE_ASSERT_TRUE(pos != node_inputs[0].attr.axis.end(), "Incorrect axis ID in vectorized_axis");
36	    uint32_t axis_id = static_cast<uint32_t>(pos - node_inputs[0].attr.axis.begin());
37	    if (axis_id < axis_ids[1]) {
38	      if (axis_id < axis_ids[0]) {
39	        axis_ids[1] = axis_ids[0];
40	        axis_ids[0] = axis_id;
41	      } else {
42	        axis_ids[1] = axis_id;
43	      }
44	    }
45	  }
46	  if (axis_ids[1] != UINT32_MAX) {
47	    if (node_inputs[0].attr.dtype == ge::DataType::DT_FLOAT16 || node_inputs[0].attr.dtype == ge::DataType::DT_FLOAT ||
48	        (node_inputs[0].attr.dtype == ge::DataType::DT_INT32 && (mode == "EQ" || mode == "NE"))) {
49	      GELOGD("[GetInputSize] axis id is: %u, %u", axis_ids[0], axis_ids[1]);
50	      GELOGD("[GetInputSize] inputs[0].repeat is: %s, %s", node_inputs[0].attr.repeats[axis_ids[0]].Str().get(),
51	             node_inputs[0].attr.repeats[axis_ids[1]].Str().get());
52	      GELOGD("[GetInputSize] inputs[0].vectorized_strides is: %s, %s",
53	             node_inputs[0].attr.vectorized_strides[0].Str().get(),
54	             node_inputs[0].attr.vectorized_strides[1].Str().get());
55	      Expression input_size =
56	          Symbol(256) * node_inputs[0].attr.repeats[axis_ids[1]] * node_inputs[0].attr.vectorized_strides[1];
57	      Expression total_size = input_size + Symbol(32) * node_inputs[0].attr.repeats[axis_ids[1]] *
58	                                               node_inputs[0].attr.vectorized_strides[1];
59	      return GetTmpBuffer(sym::Max(total_size, GetCompareNormalNoLoopTmpSize(node, axis_ids)));
60	    } else if (node_inputs[0].attr.dtype == ge::DataType::DT_INT32) {
61	      GELOGD("[GetInputSize] axis id is: %u", axis_ids[1]);
62	      GELOGD("[GetInputSize] inputs[1].repeat is: %s", node_inputs[0].attr.repeats[axis_ids[0]].Str().get());
63	      GELOGD("[GetInputSize] inputs[1].vectorized_strides is: %s",
64	             node_inputs[0].attr.vectorized_strides[1].Str().get());
65	      Expression input_size = node_inputs[0].attr.repeats[axis_ids[0]] * node_inputs[0].attr.vectorized_strides[1];
66	      Expression total_size = input_size * Symbol(256);
67	      return GetTmpBuffer(total_size);
68	    } else if (node_inputs[0].attr.dtype == ge::DataType::DT_INT64) {
69	      if (mode == "EQ" || mode == "NE") {
70	        GELOGD("[GetInputSize] axis id is: %u", axis_ids[1]);
71	        GELOGD("[GetInputSize] inputs[1].repeat is: %s", node_inputs[0].attr.repeats[axis_ids[0]].Str().get());
72	        GELOGD("[GetInputSize] inputs[1].vectorized_strides is: %s",
73	               node_inputs[0].attr.vectorized_strides[1].Str().get());
74	        Expression input_size = node_inputs[0].attr.repeats[axis_ids[0]] * node_inputs[0].attr.vectorized_strides[1];
75	        Expression total_size = input_size * Symbol(256) * Symbol(2) + Symbol(256);
76	        return GetTmpBuffer(total_size);
77	      } else {
78	        // 找到last axis, 并32字节对齐
79	        Expression last_axis_size = sym::Align(node_inputs[0].attr.repeats[vec_last_axis_pos_in_axis], 32);
80	        GELOGD("[GetInputSize] last axis size is: %s", last_axis_size.Str().get());
81	        GELOGD("[GetInputSize] axis id is: %u", axis_ids[1]);
82	        GELOGD("[GetInputSize] node_inputs[0].attr.repeats[axis_ids[0]] is: %s",
83	               node_inputs[0].attr.repeats[axis_ids[0]].Str().get());
84	        GELOGD("[GetInputSize] node_inputs[0].attr.vectorized_strides[1] is: %s",
85	               node_inputs[0].attr.vectorized_strides[1].Str().get());
86	        Expression input_size = node_inputs[0].attr.repeats[axis_ids[0]] * node_inputs[0].attr.vectorized_strides[1];
87	        GELOGD("[GetInputSize] input_size is: %s", input_size.Str().get());
88	        Expression total_size = input_size * last_axis_size * Symbol(8) * Symbol(5);
89	        TmpBufDesc desc = {total_size, -1};
90	        tmp_buf_descs.emplace_back(std::make_unique<TmpBufDesc>(desc));
91	        return tmp_buf_descs;
92	      }
93	    } else {
94	      return CalcDefaultTmpSize(node);
95	    }
96	  } else {
97	    GELOGD("[GetInputSize] axis id is: %u", axis_ids[0]);
98	    GELOGD("[GetInputSize] inputs[0].repeat is: %s", node_inputs[0].attr.repeats[axis_ids[0]].Str().get());
99	    GELOGD("[GetInputSize] inputs[0].vectorized_strides is: %s", node_inputs[0].attr.vectorized_strides[0].Str().get());
100	    Expression input_size = node_inputs[0].attr.repeats[axis_ids[0]] * node_inputs[0].attr.vectorized_strides[0];
101	    Expression total_size = Symbol(ge::GetSizeByDataType(node_inputs[0].attr.dtype)) * input_size;
102	    if (node_inputs[0].attr.dtype == ge::DataType::DT_INT64) {
103	      total_size = total_size * Symbol(5);  // Five times the temp buf is required.
104	    }
105	    return GetTmpBuffer(total_size);
106	  }
107	}
108	
109	std::vector<std::unique_ptr<TmpBufDesc>> CalcGeTmpSize(const AscNode &node) {
110	  return GetCompareNormalTmpSize(node, "GE");
111	}
112	
113	std::vector<std::unique_ptr<TmpBufDesc>> CalcEqTmpSize(const AscNode &node) {
114	  return GetCompareNormalTmpSize(node, "EQ");
115	}
116	
117	std::vector<std::unique_ptr<TmpBufDesc>> CalcNeTmpSize(const AscNode &node) {
118	  return GetCompareNormalTmpSize(node, "NE");
119	}
120	
121	std::vector<std::unique_ptr<TmpBufDesc>> CalcGtTmpSize(const AscNode &node) {
122	  return GetCompareNormalTmpSize(node, "GT");
123	}
124	
125	std::vector<std::unique_ptr<TmpBufDesc>> CalcLeTmpSize(const AscNode &node) {
126	  return GetCompareNormalTmpSize(node, "LE");
127	}
128	
129	std::vector<std::unique_ptr<TmpBufDesc>> CalcLtTmpSize(const AscNode &node) {
130	  return GetCompareNormalTmpSize(node, "LT");
131	}
132	
133	}  // namespace ascir
134	}  // namespace af
