  af::AscGraph graph("testx");
  af::Expression One = af::Symbol(1);
  af::Expression Zero = af::Symbol(0);
  Expression s1;
  Expression s2;
  CreateGraphReduce<af::DT_FLOAT>(graph, s1, s2);
