  node->inputs[0].attr.vectorized_strides = {s2, One};
  node->outputs[0].attr.vectorized_strides = {One, Zero};
  std::vector<std::unique_ptr<af::TmpBufDesc>> result = CalcReduceTmpSize(*node);
  ASSERT_EQ(result.size(), 2);
}

