22	std::vector<std::unique_ptr<TmpBufDesc>> GetTmpBuffer(const Expression &tmp_size) {
23	  auto valid_tmp_size = sym::Min(tmp_size, Symbol(MAX_REPEAT_NUM * ONE_REPEAT_BYTE_SIZE + ONE_BLK_SIZE));
24	  GELOGD("Get temp buffer size: %s", valid_tmp_size.Str().get());
25	  TmpBufDesc desc = {valid_tmp_size, -1};
26	  std::vector<std::unique_ptr<TmpBufDesc>> tmp_buf_descs;
27	  tmp_buf_descs.emplace_back(std::make_unique<TmpBufDesc>(desc));
28	  return tmp_buf_descs;
